/* ============================================================
   2. PER-VARIANT NOTE SETS
   Rows are [copyKey, controlAnchor|null, variantAnchor, overrides].
   Order = IMPROVED first, then NEW, matching the rail filters.
   Numbering is assigned sequentially per variant.
============================================================ */
const A = name => `[data-a="${name}"]`;
function build(rows){
  return rows.map((r, i) => Object.assign({}, T[r[0]], {
    n: i + 1,
    control: r[1] ? A(r[1]) : null,
    variant: A(r[2])
  }, r[3] || {}));
}

