function scrollProgress(p){
  return {y:p.scrollTop/Math.max(1,p.scrollHeight-p.clientHeight),
    x:p.scrollLeft/Math.max(1,p.scrollWidth-p.clientWidth)};
}
function controlProgress(){return vxControlUsesFrame()&&window.vxControlProgress
  ?window.vxControlProgress():scrollProgress(scrollC)}
