  if(id===activeExperimentId&&!opts.force)return true;
  if(!opts.skipCapture)captureExperimentSurface();
  activeExperimentId=id;
  activeExperiment=experimentRegistry.find(function(exp){return exp.id===id})||experimentRegistry[0];
  var state=experimentSessions[id];
  NOTES=state.notes;
  current=activeExperiment.variants.indexOf(state.current)>=0?state.current:activeExperiment.defaults.variant;
  notes=NOTES[current];
