    if(!vxBaseJourneyNotes)vxBaseJourneyNotes=vxClone(journeyInterface.notes);
    var jnotes=state.journeyNotes||vxClone(vxBaseJourneyNotes);
    journeyInterface.notes.length=0;jnotes.forEach(function(note){journeyInterface.notes.push(vxClone(note))});
    if(state.journeyCurrent){
      journeyInterface.cur.c=state.journeyCurrent.c;
      journeyInterface.cur.v=state.journeyCurrent.v;
    }
