  dismiss.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();tNotes.click();hideDismiss();showEdgeBriefly();edge.focus()});
  edge.addEventListener('click',function(){tNotes.click();setTimeout(function(){
    var key=annotationOnJourney()?'vxJRailBtn':'vxRailBtn',candidates=[document.getElementById(key),document.getElementById('vxRailOpen')];
    var focus=candidates.filter(function(el){return el&&el.offsetParent!==null})[0];if(focus)focus.focus();
  },0)});
