const reviewSurface=Object.freeze({
  get journey(){return journeyInterface},
  get notesByVariant(){return NOTES},
  get experiment(){return activeExperiment},
  get experiments(){return experimentRegistry.slice()},
  get notes(){return notes},
  get current(){return current},
  get active(){return active},
  get mode(){return mode},
  get filterKind(){return filterKind},
  get prototypeFrame(){return vxPrototypeFrame},
  prototypeSourceKey:function(){
    return vxReviewDeck==='journey'&&journeyInterface?'journey-funnel':vxPrototypeKey();
  },
  prototypeTarget:vxPrototypeTarget,
  applyFilter:filter,
  positionAnnotationTab:vxPositionAnnotationTab,
  setAnnotations:function(on){
    on=!!on;
    if(document.body.classList.contains('notes-on')!==on)tNotes.click();
    else tNotes.setAttribute('aria-pressed',String(on));
  },
  renderRail:renderRail,
  buildMarkers:buildMarkers,
  select:select,
  deselect:deselect,
  schedule:schedule,
  preview:previewInteraction,
  connectWorkflow:function(bridge,onChange){
    if(workflowBridge||workflowChangeListener)throw new Error('Review workflow may only be connected once');
    var required=['mode','path','describe','openComment','openDrawer','toast','go','setMode','cueShow','cueHide','showComment'];
    required.forEach(function(name){if(typeof bridge[name]!=='function')throw new Error('Workflow bridge is missing '+name)});
    if(typeof onChange!=='function')throw new Error('Review workflow requires one typed change listener');
    workflowBridge=Object.freeze(Object.assign({},bridge));
    workflowChangeListener=onChange;
  },
  setCurrentNotes:function(key){current=key;notes=NOTES[key]},
  activateExperiment:activateExperiment,
  captureExperiment:captureExperimentSurface,
  restoreExperiments:function(saved,id){
    saved=saved||{};
    experimentRegistry.forEach(function(exp){
      var incoming=saved[exp.id];if(!incoming)return;
      var state=experimentSessions[exp.id];
      if(incoming.notes)state.notes=vxNotesForVariants(incoming.notes,exp.variants);
      if(incoming.jnotes)state.journeyNotes=vxClone(incoming.jnotes);
      if(exp.variants.indexOf(incoming.variant)>=0)state.current=incoming.variant;
      if(incoming.viewport==='mobile'||incoming.viewport==='desktop'){
        state.mode=vxExperimentViewport(exp,incoming.viewport);
      }
      if(incoming.deck==='landing'||incoming.deck==='journey')state.deck=incoming.deck;
      if(typeof incoming.zoom==='number')state.zoom=incoming.zoom;
      if(incoming.zoomMode==='fit'||incoming.zoomMode==='free')state.zoomMode=incoming.zoomMode;
      if(typeof incoming.activeNote==='number'||incoming.activeNote===null)state.active=incoming.activeNote;
      if(['all','imp','new'].indexOf(incoming.filterKind)>=0)state.filterKind=incoming.filterKind;
      if(typeof incoming.annotationsOn==='boolean')state.annotationsOn=incoming.annotationsOn;
      state.sync=!!incoming.sync;
      if(incoming.journeyCurrent)state.journeyCurrent=vxClone(incoming.journeyCurrent);
    });
    activateExperiment(experimentSessions[id]?id:activeExperimentId,{force:true,skipCapture:true});
  },
  serializeExperiments:function(){
    captureExperimentSurface();
    var out={};
    experimentRegistry.forEach(function(exp){
      var state=experimentSessions[exp.id];
      out[exp.id]={
        notes:vxClone(state.notes),
        jnotes:vxClone(state.journeyNotes||vxBaseJourneyNotes||
          (journeyInterface?journeyInterface.notes:[])),
        variant:state.current,viewport:state.mode,deck:state.deck,
        zoom:state.zoom,zoomMode:state.zoomMode,activeNote:state.active,
        filterKind:state.filterKind,annotationsOn:state.annotationsOn,sync:state.sync,
        journeyCurrent:state.journeyCurrent?vxClone(state.journeyCurrent):null
      };
    });
    return out;
  },
  setJourneySync:function(value){journeySync=!!value}
});


/* ============================================================================
   MASTER DECK TOGGLE
   Landing page  = the control-vs-variant page comparison (deck 1)
   Journey       = the control-vs-F1 funnel step comparison (deck 2)
   window.__deck is the single source of truth both decks' handlers consult
   before touching layout, so only the visible deck ever measures or listens.
   ========================================================================= */
(function(){
  var segDeck = document.getElementById('segDeck');
  var deckLp  = document.getElementById('deck-lp');
  var deckJ   = document.getElementById('deck-journey');
  var jctl    = document.getElementById('jctl');
  var topSub  = document.getElementById('topSub');

  function setDeck(d){
    var deckName=d==='lp'?'landing':d;
    if(Array.isArray(activeExperiment.decks)&&activeExperiment.decks.indexOf(deckName)<0)return;
    experimentSessions[activeExperimentId].deck=deckName;
    var bundledJourney=d==='journey'&&!!journeyInterface;
    var genericJourney=d==='journey'&&!bundledJourney;
    vxReviewDeck=d;
    window.__deck=bundledJourney?'journey':'lp';
    deckLp.hidden=bundledJourney;
    deckJ.hidden=d!=='journey';
    jctl.hidden=!bundledJourney;
    document.body.classList.toggle('deck-journey',bundledJourney);
    document.body.classList.toggle('deck-generic-journey',genericJourney);
    segDeck.querySelectorAll('button').forEach(function(b){
      b.setAttribute('aria-pressed', String(b.dataset.d === d));
    });
    /* __lpResume re-runs updateMeta, so the subtitle restores itself */
    vxSyncExperimentPicker();
    if (bundledJourney){ topSub.textContent = 'Interstate moving journey · control vs. F1 variant'; window.__journeyResume(); }
    else window.__lpResume();
  }
  segDeck.addEventListener('click', function(e){
    var b = e.target.closest('button[data-d]');
    if (!b)return;
    var deckName=b.dataset.d==='lp'?'landing':'journey';
    if(activeExperiment.decks.indexOf(deckName)>=0)return setDeck(b.dataset.d);
    var compatible=experimentRegistry.find(function(exp){return exp.decks.indexOf(deckName)>=0});
    if(!compatible)return;
    if(workflowBridge&&typeof workflowBridge.switchExperiment==='function')
      workflowBridge.switchExperiment(compatible.id,{forceDeck:deckName});
    else activateExperiment(compatible.id,{forceDeck:deckName});
  });
  window.vxSetDeck=setDeck;
  setDeck(experimentSessions[activeExperimentId].deck==='journey'?'journey':'lp');
})();

