var vxSuppress=Date.now()+1500,vxProgWin=Date.now()+1500;
function vxSelectionChanged(detail){
  if(detail&&detail.options&&detail.options.origin==='auto')return;
  vxSuppress=Date.now()+900;vxProgWin=Date.now()+1800;
}
/* IO callbacks can be delivered AFTER a fixed suppression window expires while a
   programmatic tween is still settling — so scroll ticks inside the programmatic
   window keep pushing suppression just past themselves. User scrolls outside the
   window re-arm reveal immediately. */
['scrollC'].forEach(function(id){
  var el=document.getElementById(id);
  if(el)el.addEventListener('scroll',function(){
    if(Date.now()<vxProgWin)vxSuppress=Date.now()+450;
  },{passive:true});
});
function vxQuiet(n){
  /* select without moving the panes: the user's own scroll is the driver */
  select(n,{scroll:false,origin:'auto'});
}
var vxIOs=[];
function vxAttachAuto(){
  vxIOs.forEach(function(o){o.disconnect()});vxIOs=[];
  /* Control is rendered directly, so its native scroller remains observable.
     Variant is the live iframe now; observing the hidden review replica makes
     progressive reveal choose targets the reviewer is not actually seeing. */
  ['scrollC'].forEach(function(id){
    var root=document.getElementById(id);if(!root)return;
    var io=new IntersectionObserver(function(es){
      if(!tAuto||tAuto.getAttribute('aria-pressed')!=='true')return;
      if(document.body.classList.contains('deck-journey'))return;
      if(!document.body.classList.contains('notes-on'))return;
      if(Date.now()<vxSuppress)return;
      /* several anchors can cross the band in one callback — rank them by
         distance to the band center and make ONE deterministic selection */
      var rr=root.getBoundingClientRect();
      var bandCenter=rr.top+rr.height*0.425;
      var best=null,bestD=Infinity;
      es.forEach(function(en){
        if(!en.isIntersecting)return;
        var n=Number(en.target.dataset.an);
        if(!n||n===active)return;
        var r=en.target.getBoundingClientRect();
        var d=Math.abs((r.top+r.height/2)-bandCenter);
        if(d<bestD){bestD=d;best=n}
      });
      if(best!=null)vxQuiet(best);
    },{root:root,rootMargin:'-35% 0px -50% 0px',threshold:0});
    root.querySelectorAll('.is-anchor').forEach(function(el){io.observe(el)});
    vxIOs.push(io);
  });
}
window.vxAutoRevealVariant=function(){
  if(!tAuto||tAuto.getAttribute('aria-pressed')!=='true')return;
  if(document.body.classList.contains('deck-journey')||
     !document.body.classList.contains('notes-on')||Date.now()<vxSuppress)return;
  if(!window.vxPrototypeAnnotationRect)return;
  var frame=document.querySelector('.vx-prototype-frame');if(!frame)return;
  var rr=frame.getBoundingClientRect(),bandTop=rr.top+rr.height*.35,
      bandBottom=rr.top+rr.height*.50,bandCenter=(bandTop+bandBottom)/2,
      best=null,bestD=Infinity;
  notes.forEach(function(o){
    var r=window.vxPrototypeAnnotationRect(o.variant);if(!r)return;
    if(r.bottom<=bandTop||r.top>=bandBottom)return;
    var d=Math.abs((r.top+r.height/2)-bandCenter);
    if(d<bestD&&o.n!==active){bestD=d;best=o.n}
  });
  if(best!=null)vxQuiet(best);
};
