var vxJ={sel:-1,idxs:[],NOTES:null,STEP:null,cur:null};
function vxJourneyChanged(d){
  vxJ={sel:d.sel,idxs:d.idxs,NOTES:d.notes,STEP:d.steps,cur:d.current};vxUpdate()}
